Event Start
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
&DDO_TitleSettingsIcons = GetWWPTitleSettingsIcons() &Mes.Visible = False &Ano.Visible = False Do 'LoadComboAno' Do 'LoadComboMes'
Grid.Rows = 50 Grid_Empowerer.GridInternalName = Grid.InternalName Grid_TitlesCategories.GridInternalName = Grid.InternalName
If &HTTPRequest.Method = HttpMethod.Get Do 'LoadSavedFilters' EndIf
&prodClassificacao1 = nullvalue(&prodClassificacao1) &DynamicFiltersSelector1 = !'PRODCLASSIFICACAO' Do 'EnableDynamicFilters1'
&prodStatus = Status.Ativo DDO_Grid.GridInternalName = Grid.InternalName Form.Caption = ' Percapta de Alimentos'
Do 'PrepareTransaction' Do 'LoadGridState' If &OrderedBy < 1 &OrderedBy = 1 Do 'SetDDOSortedStatus' EndIf &DDO_TitleSettingsIcons = GetWWPTitleSettingsIcons()
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
&prodCodigoTipoRemessa.Enabled = 1 &Bercario1.Enabled = 1 &Bercario2.Enabled = 1 &Creche.Enabled = 1 &Emeb.Enabled = 1 &Integral.Enabled = 1 &Funcionarios.Enabled = 1
&BuscarDados = true
EndEvent
Event Refresh
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
LoadWWPContext.Call(&WWPContext)
Do Case Case &ManageFiltersExecutionStep = 1 &ManageFiltersExecutionStep = 2 Case &ManageFiltersExecutionStep = 2 &ManageFiltersExecutionStep = 0 Do 'LoadSavedFilters' EndCase Do 'SaveGridState'
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndEvent
Event DDO_Grid.OnOptionClicked
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
Do Case Case DDO_Grid.ActiveEventKey = !'<#OrderASC#>' OR DDO_Grid.ActiveEventKey = !'<#OrderDSC#>' &OrderedBy.FromString(DDO_Grid.SelectedValue_get) &OrderedDsc = iif(DDO_Grid.ActiveEventKey = !'<#OrderDSC#>', true, false) Do 'SetDDOSortedStatus' Grid.FirstPage() EndCase
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndEvent
Event Grid.Load
AjustesPerCaptaGravaDados(prefCodigo,&Ano,&Mes,prodCodigo,'DSP',&prodCodigoTipoRemessa,&Bercario1,&Bercario1Oferta,&Bercario2,&Bercario2Oferta,&Creche,&CrecheOferta,&Emeb,&EmebOferta,&Integral,&IntegralOferta,&Funcionarios,&FuncionariosOferta)
//msg('Produto: ' + prodCodigo.ToString().Trim() + ' - Percapta: ' + &Funcionarios.ToString().Trim() + ' - Oferta: ' + &FuncionariosOferta.ToString().Trim())
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndEvent
Event &DynamicFiltersSelector1.Click
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
Do 'EnableDynamicFilters1'
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndEvent
Event ddo_ManageFilters.OnOptionClicked
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
Do Case Case ddo_ManageFilters.ActiveEventKey = !'<#Clean#>' Do 'CleanFilters' Grid.FirstPage() Case ddo_ManageFilters.ActiveEventKey = !'<#Save#>' Do 'SaveGridState' SaveFilterAs.Popup(!'AjustePerCaptasFilters', &PgmName + !"GridState") &ManageFiltersExecutionStep = 2 Refresh Case ddo_ManageFilters.ActiveEventKey = !'<#Manage#>' ManageFilters.Popup(!'AjustePerCaptasFilters') &ManageFiltersExecutionStep = 2 Refresh Otherwise &ManageFiltersXml = GetFilterByName(!'AjustePerCaptasFilters', ddo_ManageFilters.ActiveEventKey) If &ManageFiltersXml.IsEmpty() msg('WWP_FilterNotExist') Else Do 'CleanFilters' SaveGridState.Call(&PgmName + !"GridState", &ManageFiltersXml) &GridState.FromXml(&ManageFiltersXml) &OrderedBy = &GridState.OrderedBy &OrderedDsc = &GridState.OrderedDsc Do 'SetDDOSortedStatus' Do 'LoadRegFiltersState' Do 'LoadDynFiltersState' Grid.FirstPage() EndIf EndCase
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndEvent
Event Combo_Mes.OnOptionClicked
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
&Mes.FromString(Combo_Mes.SelectedValue_get)
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
if &BuscarDados Grid.Refresh() endif
EndEvent
Event Combo_Ano.OnOptionClicked
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
&Ano.FromString(Combo_Ano.SelectedValue_get)
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
do 'LoadComboMes'
EndEvent
Sub 'SetDDOSortedStatus'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
DDO_Grid.SortedStatus = &OrderedBy.ToString().Trim() + !':' + iif(&OrderedDsc, !'DSC', !'ASC')
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'EnableDynamicFilters1'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
&prodClassificacao1.Visible = False &prodDescricao1.Visible = False &DynamicFiltersOperator1.Visible = False Do Case Case &DynamicFiltersSelector1 = !'PRODCLASSIFICACAO' &prodClassificacao1.Visible = True Case &DynamicFiltersSelector1 = !'PRODDESCRICAO' &prodDescricao1.Visible = True &DynamicFiltersOperator1.Visible = True EndCase
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'LoadSavedFilters'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
&ManageFiltersData = WWP_ManageFiltersLoadSavedFilters(!'AjustePerCaptasFilters', '', '', True)
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'CleanFilters'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
&prodStatus = Status.Ativo
&DynamicFiltersSelector1 = !'PRODCLASSIFICACAO' &prodClassificacao1.SetEmpty() Do 'EnableDynamicFilters1' &GridState.DynamicFilters.Clear() Do 'LoadDynFiltersState'
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'LoadGridState'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
// Load grid state from session. If &Session.Get(&PgmName + !"GridState") = !"" &GridState.FromXml(LoadGridState.Udp(&PgmName + !"GridState")) Else &GridState.FromXml(&Session.Get(&PgmName + !"GridState")) Endif
&OrderedBy = &GridState.OrderedBy &OrderedDsc = &GridState.OrderedDsc Do 'SetDDOSortedStatus' Do 'LoadRegFiltersState' Do 'LoadDynFiltersState'
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'LoadRegFiltersState'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
For &GridStateFilterValue in &GridState.FilterValues Do Case Case &GridStateFilterValue.Name = !"PRODSTATUS" &prodStatus.FromString(&GridStateFilterValue.Value) EndCase EndFor
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'LoadDynFiltersState'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
&DynamicFiltersOperator1.Visible = False
If &GridState.DynamicFilters.Count >= 1 &GridStateDynamicFilter = &GridState.DynamicFilters.Item(1) &DynamicFiltersSelector1 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector1 = !'PRODCLASSIFICACAO' &prodClassificacao1.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector1 = !'PRODDESCRICAO' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &prodDescricao1.FromString(&GridStateDynamicFilter.Value) EndCase Do 'EnableDynamicFilters1' EndIf
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'SaveGridState'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
&GridState.FromXml(&Session.Get(&PgmName + !"GridState"))
// Save grid state in session. &GridState.OrderedBy = &OrderedBy &GridState.OrderedDsc = &OrderedDsc &GridState.FilterValues.Clear() &AuxText = !'[' + &prodStatus + !']' WWP_GridStateAddFilterValue(&GridState, !"PRODSTATUS", "", true, 0, &prodStatus, &AuxText.Replace(!"[A]", "Ativo").Replace(!"[I]", "Inativo"), False, '', '')
Do 'SaveDynFiltersState'
SaveGridState.Call(&PgmName + !"GridState", &GridState.ToXml())
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'SaveDynFiltersState'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
&GridState.DynamicFilters.Clear() &GridStateDynamicFilter = new() &GridStateDynamicFilter.Selected = &DynamicFiltersSelector1 Do Case Case &DynamicFiltersSelector1 = !'PRODCLASSIFICACAO' AND not &prodClassificacao1.IsEmpty() &AuxText = !'[' + &prodClassificacao1.ToString().Trim() + !']' WWP_GridStateAddDynFilterValue(&GridStateDynamicFilter, "Classificação", 0, &prodClassificacao1.ToString().Trim(), &AuxText.Replace(!"[2]", "Perecíveis").Replace(!"[4]", "Semi-Perecíveis").Replace(!"[3]", "Não Perecíveis"), False, '', '') Case &DynamicFiltersSelector1 = !'PRODDESCRICAO' AND not &prodDescricao1.IsEmpty() WWP_GridStateAddDynFilterValue(&GridStateDynamicFilter, "Descrição", &DynamicFiltersOperator1, &prodDescricao1, format(!'%' + Trim(Str(&DynamicFiltersOperator1 + 1)), "WWP_FilterContains" + !' ' + &prodDescricao1, "WWP_FilterLike" + !' ' + &prodDescricao1), False, '', '') EndCase If not &GridStateDynamicFilter.Value.IsEmpty() &GridState.DynamicFilters.Add(&GridStateDynamicFilter) EndIf
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'PrepareTransaction'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
&TrnContext = new() &TrnContext.CallerObject = &Pgmname &TrnContext.CallerOnDelete = True &TrnContext.CallerURL = &HTTPRequest.ScriptName + !"?" + &HTTPRequest.QueryString &TrnContext.TransactionName = !"trnsprodutos"
&Session.Set(!"TrnContext", &TrnContext.ToXml())
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'LoadComboMes'
&Mes_Data.Clear() &Mes = Meses.Convert(&Today.Month()) &Combo_DataItem = new() &Combo_DataItem.ID = &Mes.ToString().Trim() &Combo_DataItem.Title = Meses.EnumerationDescription(&Mes) &Mes_Data.Add(&Combo_DataItem)
For Each Rancho Order prefCodigo, RanchoAno, (RanchoMes) Where RanchoAno = &Ano Where RanchoMes <> &Mes
&Combo_DataItem = new() &Combo_DataItem.ID = RanchoMes.ToString().Trim() &Combo_DataItem.Title = Meses.EnumerationDescription(RanchoMes) &Mes_Data.Add(&Combo_DataItem) EndFor
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
//&Mes initial value has to be loaded manually at the beginning of this Subrutine //&Mes_Data has to be loaded manually at the beginning of this Subrutine Combo_Mes.SelectedValue_set = iif(&Mes.IsEmpty(), '', &Mes.ToString().Trim())
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'LoadComboAno'
&Ano_Data.Clear() &Ano = &Today.Year() &Combo_DataItem = new() &Combo_DataItem.ID = &Ano.ToString().Trim() &Combo_DataItem.Title = trim(&Ano.ToFormattedString()) &Ano_Data.Add(&Combo_DataItem)
For Each Rancho Order prefCodigo, (RanchoAno) Unique RanchoAno Where prefCodigo = &prefCodigo Where RanchoAno <> &Ano
&Combo_DataItem = new() &Combo_DataItem.ID = RanchoAno.ToString().Trim() &Combo_DataItem.Title = trim(RanchoAno.ToFormattedString()) &Ano_Data.Add(&Combo_DataItem) EndFor
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
//&Ano initial value has to be loaded manually at the beginning of this Subrutine //&Ano_Data has to be loaded manually at the beginning of this Subrutine Combo_Ano.SelectedValue_set = iif(&Ano.IsEmpty(), '', &Ano.ToString().Trim())
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Event Enter
For Each Line AjustesPerCaptaGravaDados(prefCodigo,&Ano,&Mes,prodCodigo,'INS',&prodCodigoTipoRemessa,&Bercario1,&Bercario1Oferta,&Bercario2,&Bercario2Oferta,&Creche,&CrecheOferta,&Emeb,&EmebOferta,&Integral,&IntegralOferta,&Funcionarios,&FuncionariosOferta) EndFor msg('Dados gravados com sucesso!')
EndEvent

	/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */



	/* Generated by DVelop Work With Plus Pattern [End] - Do not change */

prefCodigo = &WWPContext.prefCodigo;
